"""Non-homogeneous Poisson arrivals with a piecewise-constant rate, generated by thinning."""

from __future__ import annotations

import math
from dataclasses import dataclass

import numpy as np

from cafesim.config import clock_to_seconds


@dataclass(frozen=True)
class RateFunction:
    """Piecewise-constant rate in arrival events per second, on [starts[i], ends[i])."""

    starts: tuple[float, ...]
    ends: tuple[float, ...]
    rates: tuple[float, ...]

    def __call__(self, t: float) -> float:
        for s, e, r in zip(self.starts, self.ends, self.rates, strict=True):
            if s <= t < e:
                return r
        return 0.0

    @property
    def horizon(self) -> float:
        return max(self.ends)

    @property
    def max_rate(self) -> float:
        return max(self.rates)

    def expected_count(self, a: float, b: float) -> float:
        """Integral of the rate over [a, b)."""
        total = 0.0
        for s, e, r in zip(self.starts, self.ends, self.rates, strict=True):
            lo, hi = max(a, s), min(b, e)
            if hi > lo:
                total += r * (hi - lo)
        return total


def expected_group_size(poisson_mean: float, max_size: int) -> float:
    """E[min(1 + N, max_size)] with N ~ Poisson(poisson_mean)."""
    probs = group_size_pmf(poisson_mean, max_size)
    return float(sum(k * p for k, p in probs.items()))


def group_size_pmf(poisson_mean: float, max_size: int) -> dict[int, float]:
    lam = poisson_mean
    pmf = {}
    cum = 0.0
    for k in range(1, max_size):
        p = math.exp(-lam) * lam ** (k - 1) / math.factorial(k - 1)
        pmf[k] = p
        cum += p
    pmf[max_size] = 1.0 - cum
    return pmf


def rate_function(cfg: dict) -> RateFunction:
    """Build the event-rate function (events per second) from the config."""
    arr = cfg["arrivals"]
    divisor = 1.0
    if arr["rate_unit"] == "customers":
        divisor = expected_group_size(arr["group_size"]["poisson_mean"], arr["group_size"]["max"])
    elif arr["rate_unit"] != "groups":
        raise ValueError(f"unknown rate_unit {arr['rate_unit']!r}")
    starts, ends, rates = [], [], []
    for p in arr["periods"]:
        starts.append(clock_to_seconds(p["start"]))
        ends.append(clock_to_seconds(p["end"]))
        rates.append(p["rate_per_hour"] / divisor / 3600.0)
    return RateFunction(tuple(starts), tuple(ends), tuple(rates))


def thinning_arrivals(rate: RateFunction, rng: np.random.Generator) -> np.ndarray:
    """Arrival times on [0, horizon) by Lewis-Shedler thinning against the maximum rate."""
    lam_max = rate.max_rate
    t = 0.0
    times = []
    while True:
        t += rng.exponential(1.0 / lam_max)
        if t >= rate.horizon:
            break
        if rng.random() * lam_max < rate(t):
            times.append(t)
    return np.asarray(times)


def sample_group_size(rng: np.random.Generator, poisson_mean: float, max_size: int) -> int:
    return int(min(1 + rng.poisson(poisson_mean), max_size))
